module rounded_rect_2d(x1, x2, halfw, r) {
    hull() {
        translate([x1+r, -halfw+r]) circle(r=r, $fn=48);
        translate([x2-r, -halfw+r]) circle(r=r, $fn=48);
        translate([x1+r,  halfw-r]) circle(r=r, $fn=48);
        translate([x2-r,  halfw-r]) circle(r=r, $fn=48);
    }
}

